package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.access.LateCharge;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures, as the screen shows them: a person's claimed is their counting claims' amounts added up;
 * their due-total is those claims' figures added up (a claim's figure: its settled due, else the figure a statement
 * bound it to, else its amount times the rate in force on its date of the grade in force on its date, rounded half up when the claim rounds by a date before the sheet's policy date, else half to even, and at least the sheet's floor;
 * none without a rate) with its late charge added on top while it is overdue, n/a when their grade on the sheet's today has no rate then and no counting claim keeps a settled or bound
 * figure or one at another grade. After a change, records one ROLLUP line per person whose figures it moved, then a TOTALS line when the
 * sheet's totals moved. A person's OPEN and PENDING claims dated within one of their holds count in none of these, unless a statement
 * binds them; their other claims still do.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, Audit audit) {
        this.settings = settings;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    public RollupSnapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Rate> sheetRates = rates.list(sheetId);
        List<Claim> sheetClaims = claims.list(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        LateCharge late = settings.lateCharge(sheetId, today);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        BigDecimal dueTotal = ZERO;
        for (Person p : people.list(sheetId)) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            boolean kept = false;
            for (Claim c : sheetClaims) {
                if (c.getPersonId() != p.getId() || !counts(c, p)) {
                    continue;
                }
                claimed = claimed.add(c.getAmount().setScale(2));
                kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
                String grade = p.gradeOn(c.getDate());
                BigDecimal figure = late.due(c, figure(c, grade, sheetRates, floor, late));
                // A figure at a grade other than today's does not hang on today's grade having a rate; nor does one
                // dated on or before today, whose rate may have ended since.
                kept |= figure != null && (!grade.equals(p.getGrade()) || !c.getDate().isAfter(today));
                if (figure != null) {
                    due = due.add(figure);
                }
            }
            BigDecimal personDue = kept || rateOn(sheetRates, p.getGrade(), today) != null ? due : null;
            figures.put(p.getId(), new Figures(p.getName(), claimed, personDue));
            claimedTotal = claimedTotal.add(claimed);
            if (personDue != null) {
                dueTotal = dueTotal.add(personDue);
            }
        }
        return new RollupSnapshot(figures, claimedTotal, dueTotal);
    }

    /**
     * The due-total of the counting claims dated from..to (inclusive), as the screen shows a period's: each claim's
     * figure (with its late charge) added up, a claim without one adding nothing.
     */
    public BigDecimal dueBetween(String sheetId, LocalDate from, LocalDate to) {
        List<Rate> sheetRates = rates.list(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        LateCharge late = settings.lateCharge(sheetId, sheets.today(sheetId));
        Map<Long, Person> byId = new LinkedHashMap<>();
        for (Person p : people.list(sheetId)) {
            byId.put(p.getId(), p);
        }
        BigDecimal total = ZERO;
        for (Claim c : claims.list(sheetId)) {
            Person p = byId.get(c.getPersonId());
            if (p == null || !counts(c, p) || c.getDate().isBefore(from) || c.getDate().isAfter(to)) {
                continue;
            }
            BigDecimal figure = late.due(c, figure(c, p.gradeOn(c.getDate()), sheetRates, floor, late));
            if (figure != null) {
                total = total.add(figure);
            }
        }
        return total;
    }

    /** The claim's due as the screen shows it now: its figure with its late charge on top; null (n/a) without one. */
    public BigDecimal dueOf(Claim claim) {
        String sheetId = claim.getSheetId();
        Person p = people.find(sheetId, claim.getPersonId());
        if (p == null) {
            return null;
        }
        LateCharge late = settings.lateCharge(sheetId, sheets.today(sheetId));
        return late.due(claim, figure(claim, p.gradeOn(claim.getDate()), rates.list(sheetId), settings.floor(sheetId), late));
    }

    /** Record the figures the change moved, from {@code before} to the sheet's figures now. */
    public void record(String sheetId, RollupSnapshot before, ChangedBy by) {
        RollupSnapshot after = snapshot(sheetId);
        List<String> lines = new ArrayList<>();
        String who = " sheet=" + sheetId + " by=" + by.name();
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            if (now.movedFrom(before.people().get(e.getKey()))) {
                lines.add("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed().toPlainString()
                        + " due-total=" + show(now.dueTotal()));
            }
        }
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())) {
            lines.add("TOTALS" + who + " claimed-total=" + after.claimedTotal().toPlainString() + " due-total="
                    + after.dueTotal().toPlainString());
        }
        lines.forEach(audit::record);
    }

    /** Whether the claim counts in the live totals: its person's OPEN and PENDING claims dated within a hold do not,
     *  unless a statement binds them; their other ones do. */
    private static boolean counts(Claim claim, Person person) {
        return claim.getStatus().counts() && !held(claim, person);
    }

    /** Whether a hold leaves the claim out: it is OPEN or PENDING, unbound, and dated within one of its person's holds. */
    public static boolean held(Claim claim, Person person) {
        return claim.getStatus().isOpen() && !claim.isBound() && person.heldOn(claim.getDate());
    }

    private static String show(BigDecimal figure) {
        return figure == null ? "n/a" : figure.toPlainString();
    }

    /** A claim's figure; a live one (neither settled nor bound) is at least the sheet's floor, unless it is a correction. */
    private static BigDecimal figure(Claim claim, String grade, List<Rate> sheetRates, BigDecimal floor, LateCharge late) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue().setScale(2);
        }
        if (claim.isBound()) {
            return claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2);
        }
        BigDecimal rate = rateOn(sheetRates, grade, claim.getDate());
        return claim.figureAt(rate, floor, late.rounding(claim));
    }

    /**
     * The grade's rate in force on the date: the latest from-date on or before it, none counting as the earliest; none
     * when the date is after that rate's to-date.
     */
    private static BigDecimal rateOn(List<Rate> sheetRates, String grade, LocalDate on) {
        Rate found = null;
        for (Rate r : sheetRates) {
            if (!r.grade().equals(grade) || (r.from() != null && r.from().isAfter(on))) {
                continue;
            }
            if (found == null || (r.from() != null && (found.from() == null || r.from().isAfter(found.from())))) {
                found = r;
            }
        }
        return found == null || (found.to() != null && found.to().isBefore(on)) ? null : found.rate();
    }
}
package net.officefloor.hq.app.access;

/** A setting on a sheet: its key and value (null: blank). */
public record Setting(String sheetId, String key, String value) {

    /** The most a clerk may settle a claim's due for; blank means no limit. */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The least a claim's live due may be; an amount with two decimals. */
    public static final String FLOOR = "floor";

    /** The floor a sheet starts with, until it is set. */
    public static final String FLOOR_DEFAULT = "1.00";

    /** The number of days after its date a claim is due by; a whole number. */
    public static final String TERMS = "terms";

    /** The terms a sheet starts with, until they are set. */
    public static final String TERMS_DEFAULT = "14";

    /** A grade's own terms (the key is this plus the grade, terms-A); blank means the sheet's terms. */
    public static final String TERMS_OF_GRADE = "terms-";

    /** The grades that may have their own terms. */
    public static final java.util.Set<String> GRADES = java.util.Set.of("A", "B", "C");

    /** The percent of its figure an overdue claim's due gains for every full 30 days it is overdue; two decimals. */
    public static final String LATE_PCT = "late-pct";

    /** The late percent a sheet starts with, until it is set. */
    public static final String LATE_PCT_DEFAULT = "0.00";

    /** The date before which a claim's live figures round half up, and from which half to even; blank means the sheet's today. */
    public static final String POLICY_DATE = "policy-date";

    /** The date from which (on the sheet's today) an opened claim is numbered within its period; blank means off. */
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A setting's fields: a known key and its value. The terms are a whole number of days. A grade's terms (terms-<grade>) are a whole number of days, or blank for the sheet's terms. The floor is an amount with up to two decimals. The clerk limit is an amount with up to two decimals, or blank for no limit. The late percent is a number with up to two decimals. The policy date is a date (yyyy-mm-dd), or blank for the sheet's today. Period numbering from is a date, or blank for off. */
public class ValidateSetting {

    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    public void validate(@RequestBody SettingRequest request, Out<SettingInput> setting, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String text = request == null || request.value() == null ? "" : request.value().trim();
        if (Setting.TERMS.equals(key)) {
            if (!DAYS.matcher(text).matches()) {
                throw new BadRequestException("Terms are a whole number of days");
            }
            setting.set(new SettingInput(key, String.valueOf(Integer.parseInt(text))));
            changedBy.set(by);
            return;
        }
        if (key.startsWith(Setting.TERMS_OF_GRADE) && Setting.GRADES.contains(key.substring(Setting.TERMS_OF_GRADE.length()))) {
            if (!text.isEmpty() && !DAYS.matcher(text).matches()) {
                throw new BadRequestException("A grade's terms are a whole number of days, or blank for the sheet's terms");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : String.valueOf(Integer.parseInt(text))));
            changedBy.set(by);
            return;
        }
        if (Setting.FLOOR.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A floor is an amount with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString()));
            changedBy.set(by);
            return;
        }
        if (Setting.LATE_PCT.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A late percent is a number with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString()));
            changedBy.set(by);
            return;
        }
        if (Setting.POLICY_DATE.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("A policy date is a date (yyyy-mm-dd), or blank for the sheet's today");
                }
            }
            setting.set(new SettingInput(key, date));
            changedBy.set(by);
            return;
        }
        if (Setting.PERIOD_NUMBERING_FROM.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("Period numbering from is a date (yyyy-mm-dd), or blank for off");
                }
            }
            setting.set(new SettingInput(key, date));
            changedBy.set(by);
            return;
        }
        if (!Setting.CLERK_LIMIT.equals(key)) {
            throw new BadRequestException("No such setting: " + key);
        }
        String value = null;
        if (!text.isEmpty()) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A clerk limit is an amount with up to two decimals, or blank for no limit");
            }
            value = new BigDecimal(text).setScale(2).toPlainString();
        }
        setting.set(new SettingInput(key, value));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The settings on each sheet, by key; a key without a row is blank. */
@Repository
public class SettingRepository {

    private static final RowMapper<Setting> ROW = (rs, n) -> new Setting(rs.getString("sheet_id"),
            rs.getString("setting_key"), rs.getString("setting_value"));

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings, by key; the floor, the terms and the late percent show their starting values until they are set. */
    public List<Setting> list(String sheetId) {
        List<Setting> found = new java.util.ArrayList<>(jdbc.query("SELECT sheet_id, setting_key, setting_value"
                + " FROM sheet_setting WHERE sheet_id = ? ORDER BY setting_key", ROW, sheetId));
        if (found.stream().noneMatch(s -> Setting.FLOOR.equals(s.key()))) {
            found.add(new Setting(sheetId, Setting.FLOOR, Setting.FLOOR_DEFAULT));
        }
        if (found.stream().noneMatch(s -> Setting.TERMS.equals(s.key()))) {
            found.add(new Setting(sheetId, Setting.TERMS, Setting.TERMS_DEFAULT));
        }
        if (found.stream().noneMatch(s -> Setting.LATE_PCT.equals(s.key()))) {
            found.add(new Setting(sheetId, Setting.LATE_PCT, Setting.LATE_PCT_DEFAULT));
        }
        return found;
    }

    /** The setting's value; null when blank. */
    public String find(String sheetId, String key) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?"
                + " AND setting_key = ?", ROW, sheetId, key).stream().findFirst().map(Setting::value).orElse(null);
    }

    /** The sheet's clerk limit; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        String value = find(sheetId, Setting.CLERK_LIMIT);
        return value == null ? null : new BigDecimal(value);
    }

    /** The sheet's floor: the least a claim's live due may be (1.00 until it is set). */
    public BigDecimal floor(String sheetId) {
        String value = find(sheetId, Setting.FLOOR);
        return new BigDecimal(value == null ? Setting.FLOOR_DEFAULT : value).setScale(2);
    }

    /** The sheet's terms: the days after its date a claim is due by (14 until they are set). */
    public int terms(String sheetId) {
        String value = find(sheetId, Setting.TERMS);
        return Integer.parseInt(value == null ? Setting.TERMS_DEFAULT : value);
    }

    /** The terms of the grade: its own (setting terms-<grade>), else the sheet's. */
    public int terms(String sheetId, String grade) {
        String value = grade == null ? null : find(sheetId, Setting.TERMS_OF_GRADE + grade);
        return value == null ? terms(sheetId) : Integer.parseInt(value);
    }

    /** The sheet's late percent (0.00 until it is set). */
    public BigDecimal latePct(String sheetId) {
        String value = find(sheetId, Setting.LATE_PCT);
        return new BigDecimal(value == null ? Setting.LATE_PCT_DEFAULT : value).setScale(2);
    }

    /** The sheet's policy date: the one set, else its today. */
    public java.time.LocalDate policyDate(String sheetId, java.time.LocalDate today) {
        String value = find(sheetId, Setting.POLICY_DATE);
        return value == null ? today : java.time.LocalDate.parse(value);
    }

    /** The sheet's period numbering from-date; null while off. */
    public java.time.LocalDate periodNumberingFrom(String sheetId) {
        String value = find(sheetId, Setting.PERIOD_NUMBERING_FROM);
        return value == null ? null : java.time.LocalDate.parse(value);
    }

    /** The sheet's late charge as of its today, with its policy date for rounding. */
    public LateCharge lateCharge(String sheetId, java.time.LocalDate today) {
        return new LateCharge(today, latePct(sheetId), policyDate(sheetId, today));
    }

    /** Set a setting's value (null: blank), replacing the one there before. */
    public Setting set(String sheetId, String key, String value) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key)"
                + " VALUES (?, ?, ?)", sheetId, key, value);
        return new Setting(sheetId, key, value);
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.claim.Claim;

/**
 * The late charge as of the sheet's today: an OPEN (or PENDING) claim past its due-by (fixed when it was added) gains the late
 * percent of its figure for every full 30 days it is overdue, rounded to two decimals as the claim rounds (see
 * {@link #rounding}). A correction
 * (a negative amount) never gains one. The charge is never bound by a statement; settling freezes it into the settled due.
 */
public record LateCharge(LocalDate today, BigDecimal pct, LocalDate policyDate) {

    /**
     * How the claim's live figures round: half up when it is dated before the policy date, half to even on or after
     * it. A correction rounds by the date of the claim it corrects.
     */
    public RoundingMode rounding(Claim claim) {
        return claim.getRoundOn().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The claim's late charge on its figure (zero when it is not overdue, or has no figure). */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (figure == null || !claim.getStatus().isOpen() || claim.isCorrection()) {
            return none;
        }
        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
        long periods = overdue > 0 ? overdue / 30 : 0;
        if (periods == 0) {
            return none;
        }
        return figure.multiply(pct).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, rounding(claim));
    }

    /** The figure with the claim's late charge added on top; null without a figure. */
    public BigDecimal due(Claim claim, BigDecimal figure) {
        return figure == null ? null : figure.setScale(2).add(on(claim, figure));
    }
}
